const { Worker } = require('node:worker_threads');
const { spawn } = require('node:child_process');
const vm = require('node:vm');
const hr = () => Number(process.hrtime.bigint()) / 1e6;
const codigo = "1+1";
async function proceso(n) { const t = hr(); for (let i=0;i<n;i++) await new Promise(r => spawn(process.execPath, ['-e', codigo]).on('close', r)); return (hr()-t)/n; }
async function hilo(n) { const t = hr(); for (let i=0;i<n;i++) await new Promise(r => { const w = new Worker(codigo, { eval: true }); w.on('exit', r); }); return (hr()-t)/n; }
function contexto(n) { const t = hr(); for (let i=0;i<n;i++) vm.runInNewContext(codigo, {}); return (hr()-t)/n; }
(async () => {
  await proceso(2); await hilo(3);
  const p = await proceso(20), h = await hilo(40), c = contexto(2000);
  console.log('proceso nuevo de Node  :', p.toFixed(1), 'ms por arranque');
  console.log('hilo con su propio V8  :', h.toFixed(1), 'ms por arranque');
  console.log('contexto vm (mismo V8) :', c.toFixed(3), 'ms por arranque');
})();

// Tres cuentas con precios de lista leídos el 16-11-2026 (USD). Sirven para entender las unidades, no para comprar.

// 1) Workers plan pago: 5 USD mínimo, 10 M de pedidos y 30 M de ms de CPU incluidos al mes.
function workersPago(pedidos, msCpuPorPedido) {
  const extraPedidos = Math.max(pedidos - 10e6, 0) / 1e6 * 0.30;
  const extraCpu = Math.max(pedidos * msCpuPorPedido - 30e6, 0) / 1e6 * 0.02;
  return 5 + extraPedidos + extraCpu;
}
console.log("Workers pago, 50 M pedidos de 5 ms de CPU:", workersPago(50e6, 5).toFixed(2), "USD");

// 2) R2 estándar: 0,015 USD por GB-mes (10 GB gratis), operaciones A 4,50 y B 0,36 por millón, sin cargo de egreso.
function r2(gb, millonesA, millonesB) {
  const almacenamiento = Math.max(gb - 10, 0) * 0.015;
  const a = Math.max(millonesA - 1, 0) * 4.5;
  const b = Math.max(millonesB - 10, 0) * 0.36;
  return { almacenamiento, a, b, total: almacenamiento + a + b };
}
const m = r2(500, 2, 40);
console.log("R2, 500 GB, 2 M de escrituras, 40 M de lecturas:", JSON.stringify(m, (k, v) => typeof v === "number" ? +v.toFixed(2) : v), "(egreso: 0)");

